    const persisted = await this.livestreamRepository.updateCameraPullProxyKey(
      input.cameraId,
      proxyKey,
    );
    if (!persisted || !lease.isOwned()) {
      throw new ServiceUnavailableException(
        'Không thể lưu khoá proxy camera trước khi bắt đầu livestream.',
      );
