 * endpoints this flow touches are shaped; everything else answers with an empty
 * list, which is what the tab tolerates in production.
 */
async function installHarness(
  page: Page,
  cameras: Array<Record<string, unknown>>,
  options: { createFails?: boolean; forgetKeyOnDelete?: boolean } = {},
): Promise<QrHarness> {
  const state: QrHarness = {
    createCalls: [],
    getAqpCalls: [],
    createAqpCalls: [],
    rotateAqpCalls: [],
    revokeAqpCalls: [],
    renameAqpCalls: [],
  };
  // The harness moves between every fixture state, so the variable takes their union.
  let aqpKey: typeof emptyAqpKey | typeof activeAqpKey | typeof rotatedAqpKey
    | typeof revokedAqpKey | typeof renamedActiveAqpKey = cameras.some(
    (camera) => camera.hasAqpStreamKey === true,
  )
    ? activeAqpKey
    : emptyAqpKey;
  await page.addInitScript((user) => {
    localStorage.setItem(
      'auth-storage',
      JSON.stringify({ state: { user, isAuthenticated: true }, version: 0 }),
    );
  }, organizer);

  await page.route('**/api/v1/**', async (route) => {
    const { pathname } = new URL(route.request().url());

    const createCamera = /^\/api\/v1\/livestream\/tournaments\/([^/]+)\/cameras$/.exec(pathname);
    if (createCamera && route.request().method() === 'POST') {
      state.createCalls.push(JSON.parse(route.request().postData() ?? '{}'));
      await fulfillApi(route, { data: createdPushCamera }, 201);
      return;
    }

    const aqpKeyRoute = /^\/api\/v1\/livestream\/cameras\/([^/]+)\/aqp-stream-key(?:\/rotate)?$/.exec(pathname);
    if (aqpKeyRoute && route.request().method() === 'PATCH') {
      const body = JSON.parse(route.request().postData() ?? '{}') as { stream?: string };
      state.renameAqpCalls.push({ cameraId: aqpKeyRoute[1], stream: body.stream ?? '' });
      aqpKey = renamedActiveAqpKey;
      cameras = cameras.map((camera) => {
        return camera.id === aqpKeyRoute[1]
          ? {
              ...camera,
              streamName: 'camera_renamed',
              playbackUrl: 'https://media.test/live/camera_renamed/hls.m3u8',
            }
          : camera;
      });
      await fulfillApi(route, { data: aqpKey });
      return;
    }
    if (aqpKeyRoute && route.request().method() === 'GET') {
      state.getAqpCalls.push(aqpKeyRoute[1]);
      await fulfillApi(route, { data: aqpKey });
      return;
    }
    if (aqpKeyRoute && route.request().method() === 'POST' && pathname.endsWith('/rotate')) {
      state.rotateAqpCalls.push(aqpKeyRoute[1]);
      aqpKey = rotatedAqpKey;
      await fulfillApi(route, { data: aqpKey });
      return;
    }
    if (aqpKeyRoute && route.request().method() === 'POST') {
      state.createAqpCalls.push(aqpKeyRoute[1]);
      if (options.createFails) {
        await fulfillApi(route, { statusCode: 503, message: 'AQP unavailable' }, 503);
        return;
      }
      aqpKey = aqpKey.camera.streamName === 'camera_renamed' ? renamedActiveAqpKey : activeAqpKey;
      await fulfillApi(route, { data: aqpKey }, 201);
      return;
    }
    if (aqpKeyRoute && route.request().method() === 'DELETE') {
      state.revokeAqpCalls.push(aqpKeyRoute[1]);
      // `forgetKeyOnDelete` models AQP answering 404 for the key, which makes the backend
      // clear streamKeyId: the dialog then sees a camera with no key id at all.
      aqpKey = options.forgetKeyOnDelete ? emptyAqpKey : keptAfterRevokeAqpKey;
      await fulfillApi(route, {
        data: {
          cameraId: aqpKeyRoute[1],
          keyRevoked: true,
          keptForReuse: !options.forgetKeyOnDelete,
        },
      });
      return;
    }

    if (/^\/api\/v1\/livestream\/tournaments\/[^/]+\/cameras$/.test(pathname)) {
      await fulfillApi(route, { data: cameras });
      return;
    }

    if (/^\/api\/v1\/livestream\/tournaments\/[^/]+\/matches$/.test(pathname)) {
      await fulfillApi(route, { data: [] });
      return;
    }

    if (pathname === `/api/v1/tournaments/${tournamentId}`) {
      await fulfillApi(route, {
        data: {
          id: tournamentId,
          name: 'Giải có camera QR',
          organizerId: organizer.id,
          status: 'ONGOING',
          matchType: 'SINGLES',
          genderRestriction: 'OPEN',
          entryFee: 0,
          maxParticipants: 32,
          isRegistrationLocked: false,
          category: { id: 'synthetic-qr-category', name: 'Cầu lông' },
          tournamentConfig: {},
        },
      });
      return;
    }

    if (pathname === `/api/v1/tournaments/${tournamentId}/courts`) {
      await fulfillApi(route, {
        data: {
          venue: { id: 'synthetic-qr-venue', name: 'Nhà thi đấu', locationAddress: 'Q1' },
          courts: [
            { id: 'synthetic-qr-court', courtName: 'Sân 1', venueId: 'synthetic-qr-venue', status: 'AVAILABLE' },
          ],
        },
      });
      return;
    }

    if (pathname === `/api/v1/tournaments/${tournamentId}/divisions`) {
…
