      cameraId,
      expect.any(Function),
    );
    expect(livestreamHealthQueue.runWithCameraLock.mock.invocationCallOrder[0]).toBeLessThan(
      aqvisionApiClient.delStreamProxy.mock.invocationCallOrder[0],
